-- 研究池：图灵量子 管理层 + 团队结构（2026-11-28）
-- 1) 新增 executives（创始人/董事长、CEO、财务负责人、投资方董事 4 人）
-- 2) 补 team 摘要与 execChanges：创始人 2026-04 退任 CEO、股改后董事会 9 人
-- 仅合并这四个键，不整包覆盖，避免抹掉后续人工修订
UPDATE public.research_companies
SET data = data
  || jsonb_build_object(
       'executives', '[{"name": "金贤敏", "title": "创始人、董事长、法定代表人", "role": "management", "tenure": "2021.02 至今（董事长 2023.10 起）", "shares": "间接合计 51.5%（通过上海思量量子等持股平台）", "bio": "1980 年生于安徽合肥。2002 年以总分第一考入中国科学技术大学近代物理系读研，2004–2008 师从潘建伟院士攻博，博士论文入选全国百篇优秀博士论文；2008–2010 于中科大做博士后，2010 年赴牛津大学物理系随 Ian Walmsley（时任牛津副校长、英国国家量子技术计划中心主任）做博士后，主攻光存储与光子芯片，2012 年获欧盟玛丽·居里学者与牛津沃弗森学院学者。2014 年 11 月放弃即将到手的英国绿卡全职回国，任上海交通大学长聘教授，从零组建光子集成与量子信息实验室、集成量子信息技术研究中心（IQIT）；2019 年 7 月破格晋升长聘正教授；2021 年 2 月创立图灵量子；2023 年 8 月任无锡光子芯片联合研究中心主任，2025 年起任上海交大无锡光子芯片研究院（CHIPX）院长。现为长江学者、上海交大特聘教授、光科学与技术研究所所长。发表论文 130 余篇、SCI 引用 4,500 余次（PRL 21 篇、Nature Photonics 9 篇、Science 2 篇）；2018 年制备 49×49 三维集成光量子计算芯片，为当时世界最大规模。2026 年 4 月起不再兼任 CEO，专任董事长与法定代表人，仍为实际控制人。"}, {"name": "杨林", "title": "董事、CEO（工商登记为「经理」）", "role": "management", "tenure": "2026.04 至今", "bio": "中国科学院大学博士，早期从事人工智能与量子计算相关科研工作。2022 年前后加入图灵量子，任产品开发总裁兼北京子公司总经理，主导产品研发与自研 DeepQuantum 量子编程框架——2024 年该框架成为国内首个开源的光量子计算编程框架，也是公司「编程框架松耦合、硬件紧耦合」技术战略的落点。2026 年 4 月 29 日经工商变更登记为公司董事、经理，对外以 CEO 身份出席活动、承接原由金贤敏兼任的经营管理职责；2026 年 8 月新华网《新华量子访谈》、9 月《科技日报》均以「图灵量子 CEO」称之，而官网团队页仍挂「创始人兼 CEO 金贤敏」，属未同步更新。其上任后对外表述的重心是工程化与一致性交付（IDC 机房连续运行 15 小时以上、晶圆级工艺闭环、多机并联扩展），而非再讲比特数。"}, {"name": "李桦", "title": "董事、财务负责人", "role": "management", "tenure": "2026.04 至今", "bio": "2026 年 4 月 29 日经工商变更登记为公司董事、财务负责人，与杨林同日进入，是 IPO 辅导期内把「董事 + 财务负责人」双岗补齐的标准动作，负责财务体系、内控与申报口径合规，对接国泰海通及审计机构。公开履历未披露，无技术或产业背景信息。"}, {"name": "高天垚", "title": "董事（联想之星合伙人，投资方代表）", "role": "board", "tenure": "2021.04 至今", "bio": "联想之星合伙人，2016 年加入，负责前沿科技方向的投资与投管，赛道覆盖 AI/具身智能、机器人/自动驾驶、商业航天/低空经济、芯片、能源科技与量子信息技术。2021 年 4 月即以天使轮领投方代表身份进入董事会，是公司任职最久的机构董事；对金贤敏的第一判断是「除顶尖科研实力外，对科技落地场景和商业化路径有非常清晰的思考」。主导的早期项目包括小马智行、希迪智驾、爱芯元智、海柔创新、自变量机器人、图灵量子等 40 余个。"}]'::jsonb,
       'team', '"两层结构已经成型：技术源头仍在创始人手里，日常经营交给了职业经理人。创始人金贤敏（中科大近代物理系 → 潘建伟院士博士 → 牛津 Ian Walmsley 博士后，长江学者、上海交大特聘教授、无锡光子芯片研究院院长）2026 年 4 月起不再兼任 CEO，专任董事长与法定代表人，通过上海思量量子等平台间接合计持股 51.5%，仍是实际控制人；同日中科院大学博士、原产品开发总裁杨林登记为董事、经理并出任 CEO，财务负责人李桦同期进入董事会，配合国泰海通辅导。董事会现为 9 人：金贤敏（董事长）、杨林、李桦、高天垚（联想之星合伙人，2021 年天使轮起，任职最久的机构董事）、周沛奇、郭洋、郑杭、胡志强、鲍海峰。2026-07-23 股改时范奇晖与监事施利华退出，郑杭、胡志强、鲍海峰进入，多为机构股东与员工持股平台代表，公开履历未披露。团队约 200 人、硕博占比超 70%，来源覆盖牛津、帝国理工、多伦多大学、中科院、清华、上海交大、复旦，号称国内唯一同时具备芯片制备 + 量子计算 + 光子计算 + AI 的团队；三地布局（上海闵行总部、北京中关村、无锡滨湖），母公司参保 56 人，其余挂在图灵智算量子科技（无锡）/（北京）等全资子公司。对拜访的含义：①公司已从「教授带着学生做样机」转入「职业经理人做交付、创始人管战略与政府关系」的第二阶段，问经营细节找杨林、问技术路线找金贤敏；②创始人一股独大（51.5%）+ 机构董事占多数席位，董事会里没有产业方（联想之星是财务投资人），意味着客户/供应链资源要靠合作而非股东导入；③CEO 与官网口径不一致这类细节，说明其 IR 与对外披露体系尚未按上市公司标准跑起来，辅导期内可关注其规范化进度。"'::jsonb,
       'execChanges', '[{"date": "2026-08", "event": "A 股 IPO 辅导备案获上海证监局受理（辅导机构国泰海通），预计 2027 年上半年递交申报材料"}, {"date": "2026-07-23", "event": "完成股份制改造并更名「上海图灵智算量子科技股份有限公司」；董事会由 7 人扩至 9 人，范奇晖、监事施利华退出，郑杭、胡志强、鲍海峰进入"}, {"date": "2026-04-29", "event": "工商变更：杨林登记为董事、经理并出任 CEO，李桦登记为董事、财务负责人；创始人金贤敏不再兼任 CEO，专任董事长"}, {"date": "2023-10-11", "event": "金贤敏登记为公司董事长"}, {"date": "2021-04-16", "event": "联想之星合伙人高天垚以天使轮领投方代表身份进入董事会"}, {"date": "2021-02-19", "event": "金贤敏创立上海图灵量子科技有限公司（现上海图灵智算量子科技股份有限公司）"}]'::jsonb
     ),
    updated_at = now()
WHERE name = '图灵量子';
